"""Core in-memory table representation."""

from __future__ import annotations

from typing import Any, Callable, Iterable, Iterator, Sequence


class ColumnNotFoundError(KeyError):
    """Raised when a referenced column does not exist."""


class Table:
    """A column-oriented collection of rows stored as lists.

    Missing values are represented by ``None``. Rows are validated to have the
    same width as ``columns``.
    """

    def __init__(self, columns: Sequence[str], rows: Iterable[Sequence[Any]]):
        self.columns = [str(c) for c in columns]
        if len(set(self.columns)) != len(self.columns):
            raise ValueError(f"duplicate column names: {self.columns!r}")
        width = len(self.columns)
        self._rows: list[list[Any]] = []
        for position, row in enumerate(rows):
            values = list(row)
            if len(values) != width:
                raise ValueError(
                    f"row {position} has {len(values)} values, expected {width}"
                )
            self._rows.append(values)

    @property
    def n_rows(self) -> int:
        return len(self._rows)

    @property
    def n_cols(self) -> int:
        return len(self.columns)

    @property
    def shape(self) -> tuple[int, int]:
        return (self.n_rows, self.n_cols)

    @property
    def empty(self) -> bool:
        return not self._rows or not self.columns

    def __len__(self) -> int:
        return self.n_rows

    def __iter__(self) -> Iterator[dict[str, Any]]:
        for row in self._rows:
            yield dict(zip(self.columns, row))

    def __getitem__(self, key):
        if isinstance(key, str):
            return self.column(key)
        if isinstance(key, int):
            return list(self._rows[key])
        raise TypeError("indices must be column names or row integers")

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Table):
            return NotImplemented
        return self.columns == other.columns and self._rows == other._rows

    def __repr__(self) -> str:
        return f"Table(columns={self.columns!r}, n_rows={self.n_rows})"

    def index(self, name: str) -> int:
        try:
            return self.columns.index(name)
        except ValueError as exc:
            raise ColumnNotFoundError(name) from exc

    def column(self, name: str) -> list[Any]:
        position = self.index(name)
        return [row[position] for row in self._rows]

    def column_or_none(self, name: str) -> list[Any] | None:
        if name not in self.columns:
            return None
        return self.column(name)

    def row(self, position: int) -> list[Any]:
        return list(self._rows[position])

    def head(self, n: int = 5) -> "Table":
        return Table(self.columns, self._rows[: max(n, 0)])

    def tail(self, n: int = 5) -> "Table":
        if n <= 0:
            return Table(self.columns, [])
        return Table(self.columns, self._rows[-n:])

    def to_rows(self) -> list[list[Any]]:
        return [list(row) for row in self._rows]

    def to_dicts(self) -> list[dict[str, Any]]:
        return list(self)

    def select(self, *names: str) -> "Table":
        positions = [self.index(name) for name in names]
        rows = [[row[p] for p in positions] for row in self._rows]
        return Table(names, rows)

    def filter(self, predicate: Callable[[dict[str, Any]], bool]) -> "Table":
        rows = [row for row in self._rows if predicate(dict(zip(self.columns, row)))]
        return Table(self.columns, rows)

    def sort_by(
        self,
        name: str,
        *,
        reverse: bool = False,
        key: Callable[[Any], Any] | None = None,
    ) -> "Table":
        position = self.index(name)

        def sort_key(row: list[Any]) -> Any:
            value = row[position]
            if value is None:
                return (1, None)
            if key is not None:
                value = key(value)
            return (0, value)

        rows = sorted(self._rows, key=sort_key, reverse=reverse)
        return Table(self.columns, rows)

    def rename(self, mapping: dict[str, str]) -> "Table":
        columns = [mapping.get(name, name) for name in self.columns]
        return Table(columns, self.to_rows())

    def add_column(self, name: str, values: Iterable[Any] | Callable[[dict[str, Any]], Any]) -> "Table":
        if name in self.columns:
            raise ValueError(f"column already exists: {name!r}")
        if callable(values):
            new_values = [values(record) for record in self]
        else:
            new_values = list(values)
        if len(new_values) != self.n_rows:
            raise ValueError(
                f"expected {self.n_rows} values for new column, got {len(new_values)}"
            )
        rows = [row + [value] for row, value in zip(self._rows, new_values)]
        return Table(self.columns + [name], rows)

    def drop_columns(self, *names: str) -> "Table":
        drop = {self.index(name) for name in names}
        positions = [i for i in range(self.n_cols) if i not in drop]
        columns = [self.columns[i] for i in positions]
        rows = [[row[i] for i in positions] for row in self._rows]
        return Table(columns, rows)

    def map_column(self, name: str, func: Callable[[Any], Any]) -> "Table":
        position = self.index(name)
        rows = [list(row) for row in self._rows]
        for row in rows:
            row[position] = func(row[position])
        return Table(self.columns, rows)

"""CSV loading with missing-value handling and type inference."""

from __future__ import annotations

import csv as _csv
import io
import os
import re
from typing import Any, Iterable, Sequence

from .table import Table

DEFAULT_MISSING = ("", "na", "n/a", "null", "none", "nan", "nil", "-")

_INT_RE = re.compile(r"^[+-]?\d+$")
_FLOAT_RE = re.compile(r"^[+-]?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][+-]?\d+)?$")
_TRUE = {"true", "yes"}
_FALSE = {"false", "no"}


def _clean_cell(value: Any, missing: frozenset[str], strip: bool) -> Any:
    if value is None:
        return None
    if isinstance(value, str):
        text = value.strip() if strip else value
        if text.lower() in missing:
            return None
        return text
    return value


def _classify(values: Sequence[Any]) -> str:
    present = [v for v in values if v is not None]
    if not present:
        return "str"
    if all(isinstance(v, bool) for v in present):
        return "bool"
    if all(isinstance(v, int) and not isinstance(v, bool) for v in present):
        return "int"
    if all(
        isinstance(v, (int, float)) and not isinstance(v, bool) for v in present
    ) and any(isinstance(v, float) for v in present):
        return "float"
    if all(isinstance(v, str) for v in present):
        texts = [v.strip() for v in present if v.strip()]
        if texts and all(t.lower() in _TRUE | _FALSE for t in texts):
            return "bool"
        if all(_INT_RE.match(t) for t in texts):
            return "int"
        if all(_FLOAT_RE.match(t) for t in texts):
            return "float"
    return "str"


def _convert(value: Any, kind: str) -> Any:
    if value is None:
        return None
    if not isinstance(value, str):
        return value
    text = value.strip()
    if kind == "int":
        return int(text)
    if kind == "float":
        return float(text)
    if kind == "bool":
        return text.lower() in _TRUE
    return text


def _infer_column(values: list[Any]) -> list[Any]:
    kind = _classify(values)
    if kind == "str":
        return values
    return [_convert(v, kind) for v in values]


def load_csv(
    source: str | os.PathLike[str] | io.IOBase,
    *,
    delimiter: str = ",",
    encoding: str = "utf-8",
    has_header: bool = True,
    missing_values: Iterable[str] = DEFAULT_MISSING,
    infer_types: bool = True,
    strip: bool = True,
    skip_blank_lines: bool = True,
) -> Table:
    """Load a CSV file into a :class:`~csvlab.table.Table`.

    ``source`` may be a filesystem path or an open text file object. Values
    matching ``missing_values`` (case-insensitive, after stripping) become
    ``None``. When ``infer_types`` is true each column is converted to ``int``,
    ``float``, or ``bool`` when every non-missing value qualifies.
    """

    if not isinstance(delimiter, str) or len(delimiter) != 1:
        raise ValueError("delimiter must be a single character")

    missing = frozenset(m.lower() for m in missing_values)

    close = False
    if isinstance(source, (str, os.PathLike)):
        handle: io.IOBase = open(source, "r", encoding=encoding, newline="")
        close = True
    elif hasattr(source, "read"):
        handle = source
        if isinstance(handle, io.TextIOBase) and hasattr(handle, "seek"):
            handle.seek(0)
    else:
        raise TypeError("source must be a path or an open file object")

    try:
        reader = _csv.reader(handle, delimiter=delimiter)
        raw_rows = []
        for row in reader:
            if skip_blank_lines and (not row or all(cell == "" for cell in row)):
                continue
            raw_rows.append(row)
    finally:
        if close:
            handle.close()

    if not raw_rows:
        return Table([], [])

    if has_header:
        columns = [str(c).strip() for c in raw_rows[0]]
        data = raw_rows[1:]
    else:
        width = max(len(r) for r in raw_rows)
        columns = [f"column_{i + 1}" for i in range(width)]
        data = raw_rows

    width = len(columns)
    normalised: list[list[Any]] = []
    for row in data:
        values = list(row)
        if len(values) < width:
            values.extend([None] * (width - len(values)))
        elif len(values) > width:
            values = values[:width]
        normalised.append([_clean_cell(v, missing, strip) for v in values])

    if not infer_types:
        return Table(columns, normalised)

    if not normalised:
        return Table(columns, [])

    transformed = [
        list(column)
        for column in zip(*[_infer_column(col) for col in zip(*normalised)])
    ]
    return Table(columns, transformed)


def load_csvs(
    sources: Iterable[str | os.PathLike[str]],
    *,
    **kwargs: Any,
) -> Table:
    """Load several CSVs and concatenate them, requiring identical headers."""

    frames = [load_csv(source, **kwargs) for source in sources]
    if not frames:
        return Table([], [])
    columns = frames[0].columns
    for frame in frames[1:]:
        if frame.columns != columns:
            raise ValueError(
                f"column mismatch: {frame.columns!r} != {columns!r}"
            )
    rows: list[list[Any]] = []
    for frame in frames:
        rows.extend(frame.to_rows())
    return Table(columns, rows)

