"""Data cleaning operations for :class:`~csvlab.table.Table`."""

from __future__ import annotations

import re
import statistics
from typing import Any, Callable, Iterable

from .table import Table

Scalar = Any


def _is_blank(value: Scalar) -> bool:
    return value is None or (isinstance(value, str) and value.strip() == "")


def strip_whitespace(table: Table, columns: Iterable[str] | None = None) -> Table:
    """Trim surrounding whitespace from string cells."""

    targets = set(columns) if columns is not None else set(table.columns)

    def clean(value: Scalar) -> Scalar:
        return value.strip() if isinstance(value, str) else value

    result = table
    for name in table.columns:
        if name in targets:
            result = result.map_column(name, clean)
    return result


def drop_empty_rows(table: Table) -> Table:
    rows = [row for row in table.to_rows() if not all(_is_blank(v) for v in row)]
    return Table(table.columns, rows)


def drop_empty_columns(table: Table) -> Table:
    keep = [
        name
        for name in table.columns
        if any(not _is_blank(v) for v in table.column(name))
    ]
    return table.select(*keep)


def drop_duplicates(
    table: Table,
    subset: Iterable[str] | None = None,
    *,
    keep: str = "first",
) -> Table:
    """Remove duplicate rows, optionally comparing only ``subset`` columns."""

    if keep not in {"first", "last", "none"}:
        raise ValueError("keep must be 'first', 'last' or 'none'")
    columns = list(subset) if subset is not None else list(table.columns)
    positions = [table.index(name) for name in columns]

    def signature(row: list[Any]) -> tuple:
        return tuple(row[p] for p in positions)

    rows = table.to_rows()
    if keep == "first":
        seen: set = set()
        kept = []
        for row in rows:
            sig = signature(row)
            if sig not in seen:
                seen.add(sig)
                kept.append(row)
        return Table(table.columns, kept)
    if keep == "last":
        seen = set()
        kept = []
        for row in reversed(rows):
            sig = signature(row)
            if sig not in seen:
                seen.add(sig)
                kept.append(row)
        return Table(table.columns, list(reversed(kept)))

    counts: dict[tuple, int] = {}
    for row in rows:
        sig = signature(row)
        counts[sig] = counts.get(sig, 0) + 1
    return Table(table.columns, [row for row in rows if counts[signature(row)] == 1])


def drop_missing(
    table: Table,
    subset: Iterable[str] | None = None,
    *,
    how: str = "any",
    thresh: int | None = None,
) -> Table:
    """Drop rows containing missing values.

    ``how='any'`` removes rows with any missing value, ``how='all'`` removes
    rows where every selected value is missing. ``thresh`` keeps rows with at
    least that many non-missing selected values.
    """

    if how not in {"any", "all"}:
        raise ValueError("how must be 'any' or 'all'")
    columns = list(subset) if subset is not None else list(table.columns)
    positions = [table.index(name) for name in columns]
    if thresh is None:
        if how == "any":
            keep = lambda row: all(not _is_blank(row[p]) for p in positions)
        else:
            keep = lambda row: not all(_is_blank(row[p]) for p in positions)
    else:
        keep = lambda row: sum(
            not _is_blank(row[p]) for p in positions
        ) >= thresh
    return Table(table.columns, [row for row in table.to_rows() if keep(row)])


def fill_missing(
    table: Table,
    value: Scalar = None,
    *,
    strategy: str = "value",
    columns: Iterable[str] | None = None,
) -> Table:
    """Replace missing values.

    Strategies: ``value`` (a fixed value), ``mean``, ``median``, ``mode``
    (numeric columns), ``ffill`` or ``bfill`` (last/next valid value).
    """

    targets = list(columns) if columns is not None else list(table.columns)
    valid = {"value", "mean", "median", "mode", "ffill", "bfill"}
    if strategy not in valid:
        raise ValueError(f"strategy must be one of {sorted(valid)}")

    result = table
    for name in targets:
        values = table.column(name)
        if strategy == "value":
            replacement = value
            result = result.map_column(
                name, lambda v, r=replacement: r if _is_blank(v) else v
            )
            continue
        if strategy in {"mean", "median", "mode"}:
            present = [v for v in values if not _is_blank(v)]
            if not present:
                continue
            if strategy == "mean":
                numeric = [v for v in present if isinstance(v, (int, float))]
                if not numeric:
                    continue
                replacement = statistics.mean(numeric)
            elif strategy == "median":
                numeric = [v for v in present if isinstance(v, (int, float))]
                if not numeric:
                    continue
                replacement = statistics.median(numeric)
            else:
                replacement = statistics.mode(present)
                if isinstance(replacement, (int, float)) and not isinstance(
                    replacement, bool
                ):
                    pass
            result = result.map_column(
                name, lambda v, r=replacement: r if _is_blank(v) else v
            )
            continue

        filled: list[Any] = []
        ordered = values if strategy == "ffill" else list(reversed(values))
        last: Scalar = None
        for v in ordered:
            if not _is_blank(v):
                last = v
            filled.append(last if _is_blank(v) else v)
        if strategy == "bfill":
            filled.reverse()
        positions = [table.index(name)]
        rows = result.to_rows()
        for row, replacement in zip(rows, filled):
            row[positions[0]] = replacement
        result = Table(result.columns, rows)
    return result


def rename_columns(table: Table, mapping: dict[str, str]) -> Table:
    return table.rename(mapping)


def normalize_column_names(table: Table) -> Table:
    """Convert headers to lowercase snake_case."""

    def norm(name: str) -> str:
        cleaned = re.sub(r"[^0-9a-zA-Z]+", "_", name.strip()).strip("_")
        return cleaned.lower() or "column"

    mapping: dict[str, str] = {}
    used: set[str] = set()
    for name in table.columns:
        candidate = norm(name)
        unique = candidate
        counter = 1
        while unique in used:
            counter += 1
            unique = f"{candidate}_{counter}"
        used.add(unique)
        mapping[name] = unique
    return table.rename(mapping)


_COERCIONS: dict[str, Callable[[Any], Any]] = {
    "int": lambda v: int(float(v)) if isinstance(v, str) else int(v),
    "float": float,
    "str": str,
    "bool": lambda v: (
        v.strip().lower() in {"true", "yes", "1"}
        if isinstance(v, str)
        else bool(v)
    ),
}


def coerce_types(
    table: Table,
    types: dict[str, str | Callable[[Any], Any]],
) -> Table:
    """Coerce columns to the requested type, preserving missing values."""

    result = table
    for name, target in types.items():
        table.index(name)
        if isinstance(target, str):
            if target not in _COERCIONS:
                raise ValueError(f"unknown target type: {target!r}")
            func = _COERCIONS[target]
        else:
            func = target

        def convert(value: Scalar, f: Callable[[Any], Any] = func) -> Scalar:
            if _is_blank(value):
                return None
            return f(value)

        result = result.map_column(name, convert)
    return result


def replace_values(
    table: Table,
    replacements: dict[Any, Any],
    columns: Iterable[str] | None = None,
) -> Table:
    targets = set(columns) if columns is not None else set(table.columns)
    result = table
    for name in table.columns:
        if name in targets:
            result = result.map_column(
                name, lambda v, r=replacements: r.get(v, v)
            )
    return result

"""Descriptive analysis for :class:`~csvlab.table.Table`."""

from __future__ import annotations

import math
import statistics
from typing import Any, Callable, Iterable, Sequence

from .table import Table


def _is_number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def numeric_values(values: Iterable[Any]) -> list[float]:
    return [float(v) for v in values if _is_number(v)]


def missing_count(values: Sequence[Any]) -> int:
    return sum(
        v is None or (isinstance(v, str) and v.strip() == "") for v in values
    )


def count(values: Sequence[Any]) -> int:
    return sum(
        1 for v in values if not (v is None or (isinstance(v, str) and v.strip() == ""))
    )


def total(values: Sequence[Any]) -> float:
    numbers = numeric_values(values)
    return math.fsum(numbers) if numbers else 0.0


def mean(values: Sequence[Any]) -> float | None:
    numbers = numeric_values(values)
    return statistics.mean(numbers) if numbers else None


def median(values: Sequence[Any]) -> float | None:
    numbers = numeric_values(values)
    return statistics.median(numbers) if numbers else None


def mode(values: Sequence[Any]) -> Any:
    present = [
        v for v in values if not (v is None or (isinstance(v, str) and v.strip() == ""))
    ]
    return statistics.mode(present) if present else None


def variance(values: Sequence[Any], *, sample: bool = True) -> float | None:
    numbers = numeric_values(values)
    if len(numbers) < 2:
        return 0.0 if numbers else None
    return statistics.variance(numbers) if sample else statistics.pvariance(numbers)


def stdev(values: Sequence[Any], *, sample: bool = True) -> float | None:
    numbers = numeric_values(values)
    if len(numbers) < 2:
        return 0.0 if numbers else None
    return statistics.stdev(numbers) if sample else statistics.pstdev(numbers)


def minimum(values: Sequence[Any]) -> Any:
    present = [
        v for v in values if not (v is None or (isinstance(v, str) and v.strip() == ""))
    ]
    return min(present) if present else None


def maximum(values: Sequence[Any]) -> Any:
    present = [
        v for v in values if not (v is None or (isinstance(v, str) and v.strip() == ""))
    ]
    return max(present) if present else None


def column_stats(values: Sequence[Any]) -> dict[str, Any]:
    present = [
        v for v in values if not (v is None or (isinstance(v, str) and v.strip() == ""))
    ]
    numbers = numeric_values(values)
    stats: dict[str, Any] = {
        "count": len(present),
        "missing": len(values) - len(present),
        "unique": len(set(present)),
        "min": minimum(values),
        "max": maximum(values),
        "mean": statistics.mean(numbers) if numbers else None,
        "median": statistics.median(numbers) if numbers else None,
        "stdev": (
            statistics.stdev(numbers) if len(numbers) >= 2 else (0.0 if numbers else None)
        ),
        "sum": math.fsum(numbers) if numbers else None,
    }
    return stats


def describe(
    table: Table,
    columns: Iterable[str] | None = None,
    *,
    numeric_only: bool = True,
) -> dict[str, dict[str, Any]]:
    """Return per-column summary statistics."""

    names = list(columns) if columns is not None else list(table.columns)
    out: dict[str, dict[str, Any]] = {}
    for name in names:
        values = table.column(name)
        if numeric_only and not numeric_values(values):
            continue
        out[name] = column_stats(values)
    return out


def value_counts(
    table: Table,
    column: str,
    *,
    normalize: bool = False,
    sort: bool = True,
    dropna: bool = True,
) -> list[tuple[Any, float]]:
    """Return ``(value, count)`` pairs ordered by descending frequency."""

    counts: dict[Any, int] = {}
    for value in table.column(column):
        if value is None and dropna:
            continue
        counts[value] = counts.get(value, 0) + 1
    items = list(counts.items())
    if sort:
        items.sort(key=lambda item: item[1], reverse=True)
    if normalize:
        denominator = sum(counts.values())
        if denominator == 0:
            return [(value, 0.0) for value, _ in items]
        return [(value, n / denominator) for value, n in items]
    return items


def missing_counts(table: Table) -> dict[str, int]:
    return {name: missing_count(table.column(name)) for name in table.columns}


def covariance(a: Sequence[Any], b: Sequence[Any], *, sample: bool = True) -> float | None:
    pairs = [
        (float(x), float(y))
        for x, y in zip(a, b)
        if _is_number(x) and _is_number(y)
    ]
    n = len(pairs)
    if n < 2:
        return None
    mean_x = math.fsum(x for x, _ in pairs) / n
    mean_y = math.fsum(y for _, y in pairs) / n
    total = math.fsum((x - mean_x) * (y - mean_y) for x, y in pairs)
    return total / (n - 1 if sample else n)


def correlation(table: Table, column_a: str, column_b: str) -> float | None:
    """Pearson correlation coefficient between two columns."""

    a = table.column(column_a)
    b = table.column(column_b)
    pairs = [
        (float(x), float(y))
        for x, y in zip(a, b)
        if _is_number(x) and _is_number(y)
    ]
    n = len(pairs)
    if n < 2:
        return None
    mean_x = math.fsum(x for x, _ in pairs) / n
    mean_y = math.fsum(y for _, y in pairs) / n
    numerator = math.fsum((x - mean_x) * (y - mean_y) for x, y in pairs)
    denom_x = math.sqrt(math.fsum((x - mean_x) ** 2 for x, _ in pairs))
    denom_y = math.sqrt(math.fsum((y - mean_y) ** 2 for _, y in pairs))
    if denom_x == 0 or denom_y == 0:
        return None
    return numerator / (denom_x * denom_y)


def group_by(
    table: Table,
    by: str | Sequence[str],
    aggregations: dict[str, Any],
) -> Table:
    """Aggregate rows by one or more key columns.

    ``aggregations`` maps an output column name to either a callable receiving
    the list of group records, or a ``(source_column, callable)`` pair applied
    to that column's values.
    """

    keys = [by] if isinstance(by, str) else list(by)
    for key in keys:
        table.index(key)
    key_positions = [table.index(k) for k in keys]

    groups: dict[tuple, list[dict[str, Any]]] = {}
    for record in table:
        group_key = tuple(record[k] for k in keys)
        groups.setdefault(group_key, []).append(record)

    out_rows: list[list[Any]] = []
    for group_key, records in groups.items():
        row: list[Any] = list(group_key)
        for output_name, spec in aggregations.items():
            if isinstance(spec, tuple):
                source, func = spec
                values = [record[source] for record in records]
                row.append(func(values))
            else:
                row.append(spec(records))
        out_rows.append(row)

    columns = list(keys) + list(aggregations.keys())
    return Table(columns, out_rows)

